import { useState, useEffect } from "react";
import StudentLayout from "./StudentLayout";
import api from "../api";
import axios from "axios";

const WILAYAS = ["All","Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou","Blida","Sétif","Tlemcen","Batna"];
const TYPES   = ["All","On-site","Remote","Hybrid"];
const DOMAINS = ["All","Web Dev","Mobile","Data Science","DevOps","Cybersecurity","AI/ML","Embedded"];

function OfferCard({ offer, onApply }) {
  return (
    <div className="card p-5 border rounded-xl">
      <h3 className="font-bold">{offer.title}</h3>
      <p className="text-sm text-gray-500">{offer.company_name}</p>

      <button
        onClick={() => onApply(offer)}
        className="bg-blue-600 text-white px-4 py-2 rounded-lg mt-3"
      >
        Apply
      </button>
    </div>
  );
}

function ApplyModal({ offer, onClose }) {
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);

  const handleApply = async () => {
    setLoading(true);

    try {
      const userData = JSON.parse(localStorage.getItem("user"));

      // 🔥 جلب student id الحقيقي من backend
      const res = await axios.get(
        "http://127.0.0.1:8000/api/offer",
        {
          headers: {
            Authorization:` Bearer ${userData.access}`
          }
        }
      );

      const studentId = res.data.id;

      const payload = {
        offer: offer.id,
        message: note,
        student: studentId
      };

      console.log("Payload:", payload);

      const response = await api.post(
        "http://127.0.0.1:8000/api/applications/",
        payload,
        {
          headers: {
            Authorization: `Bearer ${userData.access}`,
            "Content-Type": "application/json"
          }
        }
      );

      console.log("Success:", response.data);
      setStep(2);

    } catch (err) {
      console.error("Apply error:", err);
      alert(err.response?.data?.detail || "Error occurred");
    } finally {
      setLoading(false);
    }
  };

  if (!offer) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center">
      <div className="bg-white p-6 rounded-xl w-[400px]">

        {step === 1 && (
          <>
            <h2 className="text-lg font-bold mb-3">{offer.title}</h2>

            <textarea
              placeholder="Cover note..."
              value={note}
              onChange={(e) => setNote(e.target.value)}
              className="w-full border p-2 rounded-lg"
            />

            <div className="flex gap-2 mt-4">
              <button onClick={onClose} className="px-3 py-2 border rounded-lg">
                Cancel
              </button>

              <button
                onClick={handleApply}
                disabled={loading}
                className="bg-blue-600 text-white px-3 py-2 rounded-lg"
              >
                {loading ? "Sending..." : "Apply"}
              </button>
            </div>
          </>
        )}

        {step === 2 && (
          <div className="text-center">
            <h2 className="text-xl font-bold">Application Sent 🎉</h2>
            <button onClick={onClose} className="mt-4 bg-green-600 text-white px-4 py-2 rounded-lg">
              Done
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function StudentSearch() {
  const [offers, setOffers] = useState([]);
  const [applying, setApplying] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchOffers = async () => {
      try {
        const res = await api.get("offers/");
        setOffers(res.data);
      } catch (err) {
        console.error("Offers error:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchOffers();
  }, []);

  return (
    <StudentLayout active="search">
      <div className="p-6">

        <h1 className="text-2xl font-bold mb-4">Find Internships</h1>
        {loading ? (
          <p>Loading...</p>
        ) : (
          <div className="grid md:grid-cols-2 gap-4">
            {offers.map((offer) => (
              <OfferCard
                key={offer.id}
                offer={offer}
                onApply={setApplying}
              />
            ))}
          </div>
        )}

      </div>

      {applying && (
        <ApplyModal
          offer={applying}
          onClose={() => setApplying(null)}
        />
      )}
    </StudentLayout>
  );
}
